      if (search) {
        rows = rows.filter(
          (c) => c.companyName.toLowerCase().includes(search) || c.brandName.toLowerCase().includes(search) || c.officialEmail.toLowerCase().includes(search) || c.industry.toLowerCase().includes(search)
        );
      }
